CREATE TABLE IF NOT EXISTS richo_continuity_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id text NOT NULL UNIQUE,criticality text NOT NULL,rpo_minutes integer NOT NULL,rto_minutes integer NOT NULL,degraded_mode text NOT NULL,dependencies jsonb NOT NULL DEFAULT '[]'::jsonb,status text NOT NULL DEFAULT 'protected',correlation_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_backup_records(id uuid PRIMARY KEY,service_id text NOT NULL,created_at timestamptz NOT NULL,immutable boolean NOT NULL DEFAULT false,checksum text,verification_status text NOT NULL DEFAULT 'unverified',correlation_id text,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_restore_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),backup_id uuid NOT NULL REFERENCES richo_backup_records(id) ON DELETE CASCADE,service_id text NOT NULL,duration_minutes numeric(18,4),data_loss_minutes numeric(18,4),rto_met boolean NOT NULL,rpo_met boolean NOT NULL,checks jsonb NOT NULL DEFAULT '[]'::jsonb,verdict text NOT NULL CHECK(verdict IN('passed','failed')),correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_disaster_events(id uuid PRIMARY KEY,service_id text NOT NULL,reason text NOT NULL,severity text NOT NULL,status text NOT NULL DEFAULT 'declared' CHECK(status IN('declared','recovering','degraded','resolved','closed')),declared_by text,correlation_id text,declared_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS richo_recovery_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),disaster_id uuid NOT NULL REFERENCES richo_disaster_events(id) ON DELETE CASCADE,action text NOT NULL,status text NOT NULL,receipt jsonb NOT NULL DEFAULT '{}'::jsonb,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS richo_backup_service_idx ON richo_backup_records(service_id,created_at DESC);
